import { useRef, useState } from 'react';
import { Button, Code, Group, Input, Stack, Text, Title, useModal } from '@mantine/core';
import { useForm, type FormErrors } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { FieldEditor } from './FieldEditor/FieldEditor';
import { FieldList } from './FieldList/FieldList';
import { slugify } from './fields';
import { ModelDetails } from './ModelDetails';
import { toModelJson } from './serialize';
import type { ContentModelJson, ContentModelValues, ModelField } from './types';
import { MODEL_RULES } from './validation';

interface EditorSession {
  id: number;
  field: ModelField | null;
  takenKeys: string[];
}

export function ContentModelForm() {
  const addFieldRef = useRef<HTMLButtonElement>(null);
  const [session, setSession] = useState<EditorSession>({ id: 0, field: null, takenKeys: [] });
  const [submitted, setSubmitted] = useState<ContentModelJson | null>(null);

  const form = useForm<ContentModelValues>({
    name: 'content-model',
    initialValues: {
      name: '',
      key: '',
      description: '',
      fields: [],
    },
    validate: MODEL_RULES,
    validateInputOnBlur: ['name', 'key', 'description'],
  });

  // The key follows the name while it still equals the slug of the previous name
  form.watch('name', ({ value, previousValue }) => {
    if (form.getValues().key === slugify(previousValue)) {
      form.setFieldValue('key', slugify(value));
    }
  });

  const handleSave = (field: ModelField) => {
    const index = form.getValues().fields.findIndex((item) => item.id === field.id);
    if (index === -1) {
      form.insertListItem('fields', field);
    } else {
      form.replaceListItem('fields', index, field);
    }
    modal.close();
  };

  // A new session id remounts the editor, so every opening starts from the given field
  const modal = useModal({
    title: session.field ? 'Edit field' : 'Add field',
    size: 'lg',
    fullScreenBelow: 'sm',
    children: (
      <FieldEditor
        key={session.id}
        field={session.field}
        takenKeys={session.takenKeys}
        onSave={handleSave}
        onCancel={() => modal.close()}
      />
    ),
  });

  const openEditor = (index: number | null) => {
    const { fields } = form.getValues();
    setSession({
      id: session.id + 1,
      field: index === null ? null : fields[index],
      takenKeys: fields.filter((_, i) => i !== index).map((field) => field.key),
    });
    modal.open();
  };

  const handleSubmit = (values: ContentModelValues) => {
    const model = toModelJson(values);
    setSubmitted(model);
    notifications.show({
      title: 'Model created',
      message: `${model.key} · ${model.fields.length} ${model.fields.length === 1 ? 'field' : 'fields'}`,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    const path = Object.keys(errors)[0];
    path === 'fields' ? addFieldRef.current?.focus() : form.getInputNode(path)?.focus();
  };

  return (
    <Stack gap="xl">
      <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
        <Stack gap="xl">
          <Stack>
            <div>
              <Title order={3} c="var(--mantine-color-bright)">
                Model
              </Title>
              <Text size="sm">Entries are created from this model</Text>
            </div>
            <ModelDetails form={form} />
          </Stack>

          <Stack>
            <div>
              <Title order={3} c="var(--mantine-color-bright)">
                Fields
              </Title>
              <Text size="sm">Drag fields to change the order editors see them in</Text>
            </div>
            <FieldList
              form={form}
              addButtonRef={addFieldRef}
              onAdd={() => openEditor(null)}
              onEdit={openEditor}
            />
          </Stack>

          <Group justify="flex-end">
            <Button type="submit" onMouseDown={(event) => event.preventDefault()}>
              Create model
            </Button>
          </Group>
        </Stack>
      </form>

      {submitted && (
        <Stack gap="xs">
          <Input.Label labelElement="div">Model JSON</Input.Label>
          <Code block aria-label="Model JSON">
            {JSON.stringify(submitted, null, 2)}
          </Code>
        </Stack>
      )}
    </Stack>
  );
}

import { Checkbox, SimpleGrid, Stack, TextInput } from '@mantine/core';
import type { FieldEditorFormType } from './types';

export function CommonFieldOptions({ form }: { form: FieldEditorFormType }) {
  return (
    <Stack>
      <SimpleGrid cols={{ base: 1, sm: 2 }}>
        <TextInput
          label="Label"
          placeholder="Title"
          withAsterisk
          data-autofocus
          {...form.getInputProps('label')}
        />
        <TextInput label="Key" placeholder="title" withAsterisk {...form.getInputProps('key')} />
      </SimpleGrid>
      <TextInput
        label="Description"
        placeholder="Help text shown to editors"
        {...form.getInputProps('description')}
      />
      <Checkbox
        label="Required"
        description="Entries cannot be saved without a value"
        {...form.getInputProps('required', { type: 'checkbox' })}
      />
    </Stack>
  );
}

import { render, screen, userEvent, waitFor, within } from '@test-utils';
import { Notifications, notifications } from '@mantine/notifications';
import { ContentModelForm } from './ContentModelForm';
import { mockSortableLayout } from './sortable-layout';

type User = ReturnType<typeof userEvent.setup>;

interface FieldInput {
  type?: string;
  label: string;
  key?: string;
  required?: boolean;
}

function renderForm() {
  const user = userEvent.setup();
  render(
    <>
      <Notifications />
      <ContentModelForm />
    </>
  );
  return { user };
}

function textbox(name: string) {
  return screen.getByRole('textbox', { name });
}

function dialog() {
  return within(screen.getByRole('dialog'));
}

async function addField(user: User, { type = 'Text', label, key, required }: FieldInput) {
  await user.click(screen.getByRole('button', { name: 'Add field' }));
  await user.click(dialog().getByRole('button', { name: type }));
  await user.type(dialog().getByRole('textbox', { name: 'Label' }), label);
  if (key) {
    await user.clear(dialog().getByRole('textbox', { name: 'Key' }));
    await user.type(dialog().getByRole('textbox', { name: 'Key' }), key);
  }
  if (required) {
    await user.click(dialog().getByRole('checkbox', { name: 'Required' }));
  }
  await user.click(dialog().getByRole('button', { name: 'Save' }));
  await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
}

async function fillModel(user: User, name = 'Blog post') {
  await user.type(textbox('Model name'), name);
}

async function submit(user: User) {
  await user.click(screen.getByRole('button', { name: 'Create model' }));
}

function fieldLabels() {
  return screen
    .queryAllByRole('button', { name: /^Edit field / })
    .map((button) => button.getAttribute('aria-label')!.replace('Edit field ', ''));
}

function fieldRow(label: string) {
  return screen.getByRole('button', { name: `Edit field ${label}` }).closest('li')!;
}

function submittedModel() {
  return JSON.parse(screen.getByLabelText('Model JSON').textContent!);
}

afterEach(() => {
  notifications.clean();
  jest.restoreAllMocks();
});

describe('model details', () => {
  it('fills the key from the model name', async () => {
    const { user } = renderForm();

    await fillModel(user, 'Blog Post 2');

    expect(textbox('Model key')).toHaveValue('blog_post_2');
  });

  it('stops filling the key once it is edited by hand', async () => {
    const { user } = renderForm();
    await fillModel(user, 'Blog');
    await user.type(textbox('Model key'), '_entry');

    await user.type(textbox('Model name'), ' post');

    expect(textbox('Model key')).toHaveValue('blog_entry');
  });

  it('shows required errors for name and key and focuses the name', async () => {
    const { user } = renderForm();

    await submit(user);

    expect(screen.getByText('Model name is required')).toBeInTheDocument();
    expect(screen.getByText('Model key is required')).toBeInTheDocument();
    expect(textbox('Model name')).toHaveFocus();
  });

  it('rejects a model name shorter than 2 characters', async () => {
    const { user } = renderForm();
    await fillModel(user, 'B');

    await user.tab();

    expect(screen.getByText('Model name must be 2–60 characters')).toBeInTheDocument();
  });

  it('limits the model name to 60 characters', async () => {
    const { user } = renderForm();

    await fillModel(user, 'x'.repeat(65));

    expect(textbox('Model name')).toHaveValue('x'.repeat(60));
  });

  it('rejects a key with characters other than lowercase letters, digits and underscores', async () => {
    const { user } = renderForm();
    await user.type(textbox('Model key'), 'Blog-Post');

    await user.tab();

    expect(screen.getByText('Use lowercase letters, digits and underscores')).toBeInTheDocument();
  });

  it('clears the key error once the key is fixed', async () => {
    const { user } = renderForm();
    await user.type(textbox('Model key'), 'Blog');
    await user.tab();

    await user.clear(textbox('Model key'));
    await user.type(textbox('Model key'), 'blog');

    expect(
      screen.queryByText('Use lowercase letters, digits and underscores')
    ).not.toBeInTheDocument();
  });

  it('counts description characters up to 200', async () => {
    const { user } = renderForm();

    await user.type(textbox('Description'), 'Articles');

    expect(screen.getByText('8/200')).toBeInTheDocument();
  });
});

