    await submit(user);

    expect(submittedModel().fields.map((field: { options: unknown }) => field.options)).toEqual([
      {
        options: [
          { value: 'draft', label: 'Draft' },
          { value: 'live', label: 'Live' },
        ],
        defaultValue: 'draft',
      },
      { targetModel: 'author', allowMultiple: false },
