  listActionRef: RefObject<HTMLButtonElement | null>;
}

export const FIELD_OPTIONS: { [T in FieldType]: ComponentType<OptionsProps> | null } = {
  text: TextOptions,
  rich_text: null,
  boolean: BooleanOptions,
  json: JsonOptions,
  select: SelectOptions,
  image: null,
  file: null,
  reference: ReferenceOptions,
};

import type { ContentModelJson, ContentModelValues, FieldType, ModelField } from './types';

const noOptions = () => ({});

const FIELD_OPTIONS_JSON: { [T in FieldType]: (field: ModelField) => Record<string, unknown> } = {
  text: ({ text }) => ({
    display: text.display,
    maxLength: text.maxLength === '' ? null : Number(text.maxLength),
    defaultValue: text.defaultValue === '' ? null : text.defaultValue,
  }),
  rich_text: noOptions,
  boolean: (field) => ({ defaultValue: field.boolean.defaultValue === 'true' }),
  json: ({ json }) => ({
    defaultValue: json.defaultValue.trim() === '' ? null : JSON.parse(json.defaultValue),
  }),
  select: ({ select }) => ({
    options: select.options.map(({ value, label }) => ({
      value: value.trim(),
      label: label.trim(),
    })),
    defaultValue: select.defaultValue,
  }),
  image: noOptions,
  file: noOptions,
  reference: ({ reference }) => ({
    targetModel: reference.targetModel,
    allowMultiple: reference.multiple,
  }),
};

export function toModelJson(values: ContentModelValues): ContentModelJson {
  return {
    name: values.name.trim(),
    key: values.key,
    description: values.description.trim() || null,
    fields: values.fields.map((field) => ({
      key: field.key,
      label: field.label.trim(),
      type: field.type,
      description: field.description.trim() || null,
      required: field.required,
      options: FIELD_OPTIONS_JSON[field.type](field),
    })),
  };
}

// Test helper: jsdom has no layout, every rect is empty and the dnd-kit keyboard sensor
// finds no row to move to. Rows get stacked rects from their position among siblings.
export function mockSortableLayout() {
  return jest
    .spyOn(HTMLElement.prototype, 'getBoundingClientRect')
    .mockImplementation(function getRect(this: HTMLElement) {
      const siblings = this.parentElement ? Array.from(this.parentElement.children) : [this];
      const top = siblings.indexOf(this) * 50;
      return {
        x: 0,
        y: top,
        top,
        left: 0,
        right: 400,
        bottom: top + 40,
        width: 400,
        height: 40,
        toJSON: () => ({}),
      };
    });
}

import type { UseFormReturnType } from '@mantine/form';

export type FieldType =
